import { useMemo, useState } from 'react';
import { JxButton } from '@jinx-ui/react';

type UserStatus = 'active' | 'disabled';

interface User {
  id: string | number;
  name: string;
  role: string;
  status: UserStatus;
}

interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);

  const pageUsers = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;
    return users.slice(start, start + PAGE_SIZE);
  }, [users, currentPage]);

  const goToPage = (next: number) => {
    setPage(Math.min(Math.max(next, 1), pageCount));
  };

  return (
    <div className="jx-stack jx-stack--gap-md">
      <table className="jx-table">
        <thead className="jx-table__head">
          <tr className="jx-table__row">
            <th className="jx-table__cell jx-table__cell--header">Имя</th>
            <th className="jx-table__cell jx-table__cell--header">Роль</th>
            <th className="jx-table__cell jx-table__cell--header">Статус</th>
          </tr>
        </thead>
        <tbody className="jx-table__body">
          {pageUsers.map((user) => (
            <tr key={user.id} className="jx-table__row">
              <td className="jx-table__cell">{user.name}</td>
              <td className="jx-table__cell">{user.role}</td>
              <td className="jx-table__cell">
                <span
                  className={
                    user.status === 'active'
                      ? 'jx-badge jx-badge--success'
                      : 'jx-badge jx-badge--neutral'
                  }
                >
                  {user.status === 'active' ? 'Активен' : 'Отключён'}
                </span>
              </td>
            </tr>
          ))}
          {pageUsers.length === 0 && (
            <tr className="jx-table__row">
              <td className="jx-table__cell" colSpan={3}>
                Нет пользователей
              </td>
            </tr>
          )}
        </tbody>
      </table>

      <div className="jx-cluster jx-cluster--justify-between jx-cluster--align-center">
        <span className="jx-text jx-text--muted">
          Страница {currentPage} из {pageCount}
        </span>
        <div className="jx-cluster jx-cluster--gap-sm">
          <JxButton
            variant="secondary"
            disabled={currentPage <= 1}
            onClick={() => goToPage(currentPage - 1)}
          >
            Назад
          </JxButton>
          <JxButton
            variant="secondary"
            disabled={currentPage >= pageCount}
            onClick={() => goToPage(currentPage + 1)}
          >
            Вперёд
          </JxButton>
        </div>
      </div>
    </div>
  );
}

